import{_ as o,b as i,c as a,g as e}from"./chunks/framework.86O3EbG5.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/19.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/19.md"}'),n={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/19.md"};function s(r,t,d,p,c,g){return i(),a("div",null,[...t[0]||(t[0]=[e('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 19 章&lt;样例学习&gt;，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来</p><h2 id="简述bagging和boosting在训练方式、基模型权重、主要解决偏差-方差问题三个方面的区别。举例说明-为什么随机森林比单棵决策树更不容易过拟合" tabindex="-1">简述Bagging和Boosting在训练方式、基模型权重、主要解决偏差/方差问题三个方面的区别。举例说明：为什么随机森林比单棵决策树更不容易过拟合？</h2><h2 id="随机森林在构建每棵决策树时引入两种随机性-一是bootstrap采样-二是随机特征子集-每次分裂随机选择部分特征-。分别说明这两种随机性如何增加基模型多样性。如果去掉特征子集采样-只保留bootstrap-对集成的方差和偏差有何影响" tabindex="-1">随机森林在构建每棵决策树时引入两种随机性：一是Bootstrap采样，二是随机特征子集（每次分裂随机选择部分特征）。分别说明这两种随机性如何增加基模型多样性。如果去掉特征子集采样，只保留Bootstrap，对集成的方差和偏差有何影响？</h2><h2 id="有三个独立的二分类器-准确率均为0-6-略优于随机-假设各分类器的误差相互独立。使用多数投票法集成后-集成分类器的准确率是多少-如果三个分类器的准确率都是0-9-集成后准确率又是多少-提示-计算多数投票错误概率" tabindex="-1">有三个独立的二分类器，准确率均为0.6（略优于随机），假设各分类器的误差相互独立。使用多数投票法集成后，集成分类器的准确率是多少？如果三个分类器的准确率都是0.9，集成后准确率又是多少？（提示：计算多数投票错误概率）</h2><h2 id="adaboost权重更新模拟-给定6个样本-初始权重均为1-6。第一轮训练后-分类器错误率为1-3-错误样本索引为-2-4-5-。" tabindex="-1">AdaBoost权重更新模拟：给定6个样本，初始权重均为1/6。第一轮训练后，分类器错误率为1/3，错误样本索引为{2,4,5}。</h2><p>(1) 计算该分类器的权重系数 α=1/2 ln⁡(1-ϵ)/ϵ。 (2) 更新样本权重（正确样本权重乘 e^(-α)，错误样本乘 e^α），然后归一化。写出归一化后的权重（精确分数或保留三位小数）。</p><h2 id="随机森林特征重要性-随机森林可以通过两种方式衡量特征重要性-一种是基于gini不纯度减少的平均值-另一种是基于置换-permutation-精度下降。请简述这两种方法的原理-并说明哪种方法更能反映特征对模型泛化性能的真实贡献。" tabindex="-1">随机森林特征重要性：随机森林可以通过两种方式衡量特征重要性：一种是基于Gini不纯度减少的平均值，另一种是基于置换（permutation）精度下降。请简述这两种方法的原理，并说明哪种方法更能反映特征对模型泛化性能的真实贡献。</h2><h2 id="stacking与交叉验证-你有3个基模型-m1-m2-m3-和一个元学习器。训练集大小为1000。请描述如何使用5折交叉验证为每个训练样本生成元特征-即每个基模型对该样本的预测输出-。画出划分示意图-并说明生成元特征矩阵的维度。为什么不能简单地在整个训练集上训练基模型-然后用这些模型预测训练集来生成元特征" tabindex="-1">Stacking与交叉验证：你有3个基模型（M1, M2, M3）和一个元学习器。训练集大小为1000。请描述如何使用5折交叉验证为每个训练样本生成元特征（即每个基模型对该样本的预测输出）。画出划分示意图，并说明生成元特征矩阵的维度。为什么不能简单地在整个训练集上训练基模型，然后用这些模型预测训练集来生成元特征？</h2><h2 id="集成方法对比实验-在一个中等规模数据集-特征数100-样本数2000-二分类-上-你想比较逻辑回归、随机森林-100棵树-、xgboost的性能。" tabindex="-1">集成方法对比实验：在一个中等规模数据集（特征数100，样本数2000，二分类）上，你想比较逻辑回归、随机森林（100棵树）、XGBoost的性能。</h2><p>(1) 设计实验流程，包括数据划分、超参数调优（随机森林的树深度、特征数；XGBoost的学习率、树个数）、性能评估指标（如AUC、F1）。 (2) 假设随机森林和XGBoost训练时间较长（各需10分钟），而逻辑回归只需10秒，但逻辑回归的AUC=0.80，随机森林AUC=0.85，XGBoost AUC=0.86。你会选择哪个模型？为什么？ (3) 如何判断集成模型是否过拟合？画出学习曲线（训练误差和验证误差随训练样本数变化的曲线）并解释。</p><h2 id="偏差-方差分解与集成" tabindex="-1">偏差-方差分解与集成：</h2><p>(1) 对于平方误差损失，证明独立同分布的 m 个基模型平均后，期望平方误差的方差部分降低为原来的 1/m（假设基模型无偏）。 (2) 实际上基模型通常不是独立的，为什么Bagging（如随机森林）仍然能有效降低方差？ (3) Boosting（如AdaBoost）在训练过程中，基模型的相关性如何变化？这是否会导致方差增大？为什么Boosted树仍能提升性能？</p><h2 id="堆叠法的过拟合防范-在使用stacking时-如果在整个训练集上训练基模型-然后用这些模型预测训练集得到的元特征来训练元学习器-会造成什么问题-请给出两种正确生成元特征的方法-避免信息泄露。" tabindex="-1">堆叠法的过拟合防范：在使用Stacking时，如果在整个训练集上训练基模型，然后用这些模型预测训练集得到的元特征来训练元学习器，会造成什么问题？请给出两种正确生成元特征的方法，避免信息泄露。</h2><h2 id="金融信用评分集成系统-你需要为一个网贷平台设计信用评分模型-判断借款人是否会违约。可用的基模型包括-逻辑回归、决策树-深度5-、支持向量机-线性核-、k近邻-k-15-。" tabindex="-1">金融信用评分集成系统：你需要为一个网贷平台设计信用评分模型，判断借款人是否会违约。可用的基模型包括：逻辑回归、决策树（深度5）、支持向量机（线性核）、K近邻（K=15）。</h2><p>(1) 从算法多样性角度，你会选择哪种集成策略（Bagging、Boosting、Stacking或 Voting）？说明理由。 (2) 描述完整的训练流程（数据预处理、基模型训练、集成方法、超参数调优）。 (3) 系统部署后，发现假阳性（将好客户误判为违约）比例较高，平台希望降低该比例。你如何调整集成模型的决策阈值？如果使用AdaBoost，如何调整阈值或引入代价敏感学习？ (4) 模型需要每月更新以适应新的借款数据，你会采用离线重训练还是在线学习？简述理由。</p>',15)])])}const m=o(n,[["render",s]]);export{l as __pageData,m as default};
